'use strict';
// Optional local WASM inference. No request ever contains image pixels.
importScripts('vendor/ort/ort.wasm.min.js');
ort.env.wasm.wasmPaths=new URL('vendor/ort/',self.location.href).href;
ort.env.wasm.numThreads=1;
const FILES=[['mobile_sam_image_encoder.onnx','580f5fb648ea1062c0aabc26217aed56921985f03f0cbbd852bba81d760cc749'],['sam_mask_decoder_single.onnx','93915fc7c993ab9d59ab8c9ccd3bce37f7509c81ab4150a74abd4d2abbd8570d']];
const progress=text=>postMessage({progress:text});
async function modelsDatabase(){return new Promise((resolve,reject)=>{const req=indexedDB.open('rasm-local-models',1);req.onupgradeneeded=()=>req.result.createObjectStore('models');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function loadModel(name,hash){let blob;const db=await modelsDatabase();try{blob=await new Promise((resolve,reject)=>{const req=db.transaction('models').objectStore('models').get(name);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}finally{db.close()}
 if(!blob){const response=await fetch('models/'+name);if(!response.ok)throw Error('حزمة التحليل الاختيارية غير مثبتة. استخدم زر تثبيت النموذج واختر ملفي ONNX. يمكنك مراجعة مكونات الحبر أو استيراد الأقنعة دون النموذج.');blob=await response.blob()}
 const buffer=await blob.arrayBuffer(),actual=[...new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))].map(v=>v.toString(16).padStart(2,'0')).join('');if(actual!==hash)throw Error('ملف نموذج التحليل غير مطابق للإصدار الموثق. لم يتم تشغيله.');return new Uint8Array(buffer)
}
function runs(mask){const values=[];for(let p=0;p<mask.length;){if(!mask[p]){p++;continue}const start=p;while(p<mask.length&&mask[p])p++;values.push(start,p-start)}return values}
self.onmessage=async event=>{let encoder,decoder,embedding,inputs;const started=performance.now();try{const {width,height}=event.data,pixels=new Uint8ClampedArray(event.data.pixels);if(!width||!height||pixels.length!==width*height*4||width*height>4_000_000)throw Error('أبعاد صورة التحليل غير صالحة.');
 progress('تحميل النموذج المحلي والتحقق منه…');encoder=await ort.InferenceSession.create(await loadModel(...FILES[0]),{executionProviders:['wasm'],graphOptimizationLevel:'all'});decoder=await ort.InferenceSession.create(await loadModel(...FILES[1]),{executionProviders:['wasm'],graphOptimizationLevel:'all'});
 const scale=1024/Math.max(width,height),rw=Math.round(width*scale),rh=Math.round(height*scale),source=new OffscreenCanvas(width,height),resized=new OffscreenCanvas(rw,rh);source.getContext('2d').putImageData(new ImageData(pixels,width,height),0,0);const rc=resized.getContext('2d');rc.drawImage(source,0,0,rw,rh);const rgba=rc.getImageData(0,0,rw,rh).data,rgb=new Float32Array(rw*rh*3);for(let p=0;p<rw*rh;p++){rgb[p*3]=rgba[p*4];rgb[p*3+1]=rgba[p*4+1];rgb[p*3+2]=rgba[p*4+2]}
 progress('تحليل الصورة على هذا الجهاز…');const input=new ort.Tensor('float32',rgb,[rh,rw,3]),encoded=await encoder.run({input_image:input});input.dispose();embedding=encoded[encoder.outputNames[0]];for(const [name,tensor]of Object.entries(encoded))if(name!==encoder.outputNames[0])tensor.dispose();await encoder.release();encoder=null;
 const fg=new Uint8Array(width*height);for(let p=0;p<fg.length;p++){const q=p*4;fg[p]=Math.hypot((pixels[q]-255)*.92,pixels[q+1]-255,(pixels[q+2]-255)*.92)>=26?1:0}
 inputs={image_embeddings:embedding,point_coords:new ort.Tensor('float32',new Float32Array(4),[1,2,2]),point_labels:new ort.Tensor('float32',new Float32Array([1,-1]),[1,2]),mask_input:new ort.Tensor('float32',new Float32Array(256*256),[1,1,256,256]),has_mask_input:new ort.Tensor('float32',new Float32Array([0]),[1]),orig_im_size:new ort.Tensor('float32',new Float32Array([height,width]),[2])};const candidates=[];
 for(let row=0;row<9;row++){
  for(let col=0;col<16;col++){inputs.point_coords.data[0]=(col+.5)*width/16*scale;inputs.point_coords.data[1]=(row+.5)*height/9*scale;const outputs=await decoder.run(inputs),logits=outputs[decoder.outputNames[0]].data,score=outputs[decoder.outputNames[1]].data[0];let area=0,inkCount=0;const mask=new Uint8Array(fg.length),ink=new Uint8Array(fg.length);for(let p=0;p<mask.length;p++)if(logits[p]>0){mask[p]=1;area++;if(fg[p]){ink[p]=1;inkCount++}}for(const tensor of Object.values(outputs))tensor.dispose();if(score<.85||area<300||area>width*height*.55||inkCount<100||candidates.length>=60)continue;let duplicate=false;for(const previous of candidates){let intersection=0;for(let p=0;p<mask.length;p++)if(mask[p]&&previous.mask[p])intersection++;if(intersection/(area+previous.area-intersection)>.85){duplicate=true;break}}if(!duplicate)candidates.push({mask,ink,area,inkCount,score})}
  progress('اقتراحات محلية: '+(row+1)+'/9 · '+candidates.length+' قناع قيد المراجعة');
 }
 candidates.sort((a,b)=>b.inkCount-a.inkCount);postMessage({seconds:(performance.now()-started)/1000,proposals:candidates.map((c,i)=>({name:'اقتراح '+(i+1),runs:runs(c.ink),width,height,modelScore:c.score}))});
 }catch(error){postMessage({error:'تعذّر التحليل المحلي: '+String(error.message||error)+'. لا تزال المراجعة اليدوية متاحة.'})}finally{if(inputs)for(const tensor of Object.values(inputs))if(tensor!==embedding)tensor.dispose();embedding?.dispose();await encoder?.release();await decoder?.release()}};
